import React, { useState, useEffect } from 'react';
import './PostForm.css';

const PostForm = ({ onSubmit, onUpdate, editingPost, onCancelEdit, loading }) => {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [publishedDate, setPublishedDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');

  // If editing a post, populate form with that post's details
  useEffect(() => {
    if (editingPost) {
      setTitle(editingPost.title || '');
      setAuthor(editingPost.author || '');
      setPublishedDate(
        editingPost.publishedDate
          ? new Date(editingPost.publishedDate).toISOString().split('T')[0]
          : ''
      );
      setContent(editingPost.content || '');
    } else {
      setTitle('');
      setAuthor('');
      setPublishedDate(new Date().toISOString().split('T')[0]);
      setContent('');
    }
  }, [editingPost]);

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!title.trim() || !author.trim() || !content.trim()) {
      alert('Please fill out all required fields.');
      return;
    }

    const postData = {
      title,
      author,
      publishedDate,
      content
    };

    if (editingPost) {
      onUpdate(editingPost._id, postData);
    } else {
      onSubmit(postData);
      // Reset form fields
      setTitle('');
      setAuthor('');
      setContent('');
    }
  };

  return (
    <div className="card shadow-sm">
      <div className="card-header bg-white py-3">
        <h5 className="mb-0 text-primary fw-bold">
          {editingPost ? 'Edit Post' : 'Create New Post'}
        </h5>
      </div>

      <div className="card-body">
        <form onSubmit={handleSubmit}>
          {/* Title */}
          <div className="mb-3">
            <label className="form-label fw-semibold">Title</label>
            <input
              type="text"
              className="form-control"
              placeholder="Enter post title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          {/* Author */}
          <div className="mb-3">
            <label className="form-label fw-semibold">Author</label>
            <input
              type="text"
              className="form-control"
              placeholder="Enter author name"
              value={author}
              onChange={(e) => setAuthor(e.target.value)}
              required
            />
          </div>

          {/* Published Date */}
          <div className="mb-3">
            <label className="form-label fw-semibold">Published Date</label>
            <input
              type="date"
              className="form-control"
              value={publishedDate}
              onChange={(e) => setPublishedDate(e.target.value)}
              required
            />
          </div>

          {/* Content */}
          <div className="mb-3">
            <label className="form-label fw-semibold">Content</label>
            <textarea
              className="form-control"
              rows="5"
              placeholder="Write your blog post content here..."
              value={content}
              onChange={(e) => setContent(e.target.value)}
              required
            ></textarea>
          </div>

          {/* Action Buttons */}
          <div className="d-flex gap-2">
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {editingPost ? 'Update Post' : 'Publish Post'}
            </button>
            {editingPost && (
              <button type="button" className="btn btn-secondary" onClick={onCancelEdit}>
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

export default PostForm;
